import type { BankQuestion } from "@/lib/bank";

/** Indian Economy Basics (Economy): 133 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eco-basics-1","question":"GDP stands for:","options":["Gross Domestic Product","General Development Programme","Gross Development Product","Grand Domestic Production"],"answer":0,"explanation":"GDP is the total value of final goods and services produced within a country in a year.","difficulty":"easy"},
  {"id":"eco-basics-2","question":"GST was implemented in India from:","options":["1 April 2016","1 July 2017","1 January 2018","1 April 2017"],"answer":1,"explanation":"GST came into force on 1 July 2017.","difficulty":"easy"},
  {"id":"eco-basics-3","question":"The rate at which the RBI lends money to commercial banks is called the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"The repo rate is the rate at which the RBI lends to banks against government securities.","difficulty":"moderate"},
  {"id":"eco-basics-4","question":"NITI Aayog replaced which body?","options":["Finance Commission","Planning Commission","National Development Council","Election Commission"],"answer":1,"explanation":"NITI Aayog replaced the Planning Commission on 1 January 2015.","difficulty":"moderate"},
  {"id":"eco-basics-5","question":"The RBI was nationalised in:","options":["1935","1947","1949","1969"],"answer":2,"explanation":"The RBI was nationalised on 1 January 1949.","difficulty":"moderate"},
  {"id":"eco-basics-6","question":"GST was introduced through which Constitutional Amendment?","options":["100th","101st","102nd","103rd"],"answer":1,"explanation":"The 101st Constitutional Amendment Act, 2016 enabled GST.","difficulty":"hard"},
  {"id":"eco-basics-7","question":"The rate at which the RBI borrows money from commercial banks is called the:","options":["Repo rate","Reverse repo rate","Bank rate","MSF rate"],"answer":1,"explanation":"Under the reverse repo, banks park surplus funds with the RBI and earn interest.","difficulty":"hard"},
  {"id":"eco-basics-8","question":"Which of the following is an indirect tax?","options":["Income tax","Corporate tax","GST","Wealth tax"],"answer":2,"explanation":"GST is levied on goods and services and passed on to the consumer, so it is indirect.","difficulty":"hard"},
  {"id":"eco-basics-9","question":"The Fiscal Responsibility and Budget Management (FRBM) Act was enacted in:","options":["1991","2003","2005","2016"],"answer":1,"explanation":"The FRBM Act, 2003 set targets for reducing the fiscal deficit.","difficulty":"very-hard"},
  {"id":"eco-basics-10","question":"Who was the first Governor of the Reserve Bank of India?","options":["C. D. Deshmukh","Sir Osborne Smith","James Braid Taylor","Benegal Rama Rau"],"answer":1,"explanation":"Sir Osborne Smith was the first Governor (1935–37); C. D. Deshmukh was the first Indian Governor.","difficulty":"very-hard"},
  {"id":"eco-basics-11","question":"The Minimum Support Price (MSP) for crops is recommended by the:","options":["NITI Aayog","Commission for Agricultural Costs and Prices (CACP)","Food Corporation of India","Ministry of Finance"],"answer":1,"explanation":"The CACP recommends MSPs; the Cabinet Committee on Economic Affairs approves them.","difficulty":"very-hard"},
  {"id":"eco-basics-12","question":"The Reserve Bank of India was established in:","options":["1921","1935","1947","1949"],"answer":1,"explanation":"The RBI started on 1 April 1935 under the RBI Act, 1934, and was nationalised in 1949.","difficulty":"easy","source":"SSC CGL · IBPS PO"},
  {"id":"eco-basics-13","question":"Inflation measured on the basis of the wholesale price of goods uses the index:","options":["CPI","WPI","GDP deflator","PPI"],"answer":1,"explanation":"WPI tracks wholesale prices; CPI tracks retail prices paid by consumers.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"eco-basics-14","question":"The rate at which the RBI lends short-term funds to commercial banks against securities is the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"Repo is the RBI’s lending rate; reverse repo is what it pays banks for their deposits.","difficulty":"moderate","source":"IBPS PO · SBI PO"},
  {"id":"eco-basics-15","question":"Which of these is NOT a direct tax?","options":["Income tax","Corporation tax","Goods and Services Tax","Wealth tax"],"answer":2,"explanation":"GST is an indirect tax, passed on to the consumer.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"eco-basics-16","question":"The “Hindu rate of growth”, describing India’s slow growth before the 1980s, was coined by:","options":["Amartya Sen","Raj Krishna","C. Rangarajan","Jagdish Bhagwati"],"answer":1,"explanation":"Economist Raj Krishna used the phrase for the roughly 3.5% growth of 1950–80.","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"eco-basics-17","question":"Fiscal deficit equals:","options":["Revenue receipts − revenue expenditure","Total expenditure − total receipts excluding borrowings","Total receipts − total expenditure","Interest payments − revenue deficit"],"answer":1,"explanation":"Fiscal deficit is the gap that must be met by borrowing.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO"},
  {"id":"eco-basics-18","question":"Consider: 1. The repo rate is a quantitative tool of credit control. 2. Raising the CRR increases money supply. 3. Open market operations mean buying and selling government securities. Which are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"A higher CRR locks up more bank money with the RBI and reduces money supply.","difficulty":"hard"},
  {"id":"eco-basics-19","question":"GDP at market price minus depreciation equals:","options":["GNP at market price","NDP at market price","NNP at factor cost","GDP at factor cost"],"answer":1,"explanation":"Subtracting depreciation turns “gross” into “net”: NDP at market price.","difficulty":"hard"},
  {"id":"eco-basics-20","question":"If net factor income from abroad is negative, then:","options":["GNP > GDP","GNP < GDP","GNP = GDP","NNP > GNP"],"answer":1,"explanation":"GNP = GDP + net factor income from abroad, so a negative NFIA makes GNP smaller.","difficulty":"very-hard"},
  {"id":"eco-basics-21","question":"Fiscal deficit minus interest payments is called the:","options":["Revenue deficit","Primary deficit","Effective revenue deficit","Budget deficit"],"answer":1,"explanation":"Primary deficit shows borrowing needed for current spending other than interest.","difficulty":"very-hard"},
  {"id":"eco-basics-22","question":"How many of these statements are correct? I. GST came into force on 1 July 2017. II. The GST Council is chaired by the Union Finance Minister. III. Alcohol for human consumption is outside GST. IV. Crude petroleum is currently taxed under GST.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Crude, diesel, petrol, natural gas and ATF are not yet taxed under GST.","difficulty":"very-hard"},
  {"id":"eco-basics-23","question":"How many of these statements are correct? I. Stagflation means high inflation with stagnant growth. II. Deflation is a fall in the general price level. III. Disinflation means the general price level is falling.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Disinflation is a fall in the rate of inflation; prices still rise, just more slowly.","difficulty":"very-hard"},
  {"id":"eco-basics-24","question":"How many of these statements are correct? I. GDP at factor cost = GDP at market prices − net indirect taxes. II. NNP = GNP − depreciation. III. GNP = GDP + net factor income from abroad.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are standard national-income identities.","difficulty":"very-hard"},
  {"id":"eco-basics-25","question":"Which measure of money supply is called “broad money”?","options":["M1","M2","M3","M4"],"answer":2,"explanation":"M3 (M1 plus time deposits with banks) is broad money; M1 is narrow money.","difficulty":"very-hard"},
  {"id":"eco-basics-26","question":"If the RBI raises the cash reserve ratio, what follows?","options":["The money multiplier falls","The money multiplier rises","Banks have more funds to lend","The repo rate falls automatically"],"answer":0,"explanation":"The money multiplier is roughly 1 ÷ reserve ratio, so a higher CRR shrinks it and leaves banks less to lend.","difficulty":"very-hard"},
  {"id":"eco-basics-27","question":"How many of these statements are correct? I. Revenue deficit = revenue expenditure − revenue receipts. II. Effective revenue deficit = revenue deficit − grants given for the creation of capital assets. III. Disinvestment proceeds are capital receipts. IV. Interest payments are capital expenditure.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Interest payments create no asset, so they are revenue expenditure.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO"},
  {"id":"eco-basics-28","question":"Banks must hold reserves equal to 20% of deposits. If the central bank adds ₹1,000 crore of fresh reserves to the system, the maximum increase in deposits under the simple multiplier is:","options":["₹5,000 crore","₹2,000 crore","₹1,200 crore","₹20,000 crore"],"answer":0,"explanation":"Deposit multiplier = 1 ÷ reserve ratio = 1 ÷ 0.2 = 5, so ₹1,000 crore can support ₹5,000 crore of deposits.","difficulty":"very-hard","source":"IBPS PO · UPSC Prelims"},
  {"id":"eco-basics-29","question":"The headquarters of NITI Aayog is located in:","options":["Mumbai","New Delhi","Kolkata","Hyderabad"],"answer":1,"explanation":"NITI Aayog, which replaced the Planning Commission on 1 January 2015, is headquartered in New Delhi with the Prime Minister as its chairperson.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-30","question":"The Union Budget of India is presented in the Lok Sabha by the:","options":["President","Prime Minister","Finance Minister","RBI Governor"],"answer":2,"explanation":"The Annual Financial Statement under Article 112 is laid before Parliament by the Union Finance Minister on behalf of the President.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-31","question":"Per capita income of a country is obtained by dividing its national income by its:","options":["Area","Labour force","Population","Number of households"],"answer":2,"explanation":"Per capita income = national income ÷ total population; it is an average and says nothing about how income is distributed.","difficulty":"easy","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-32","question":"Which sector contributes the largest share to India’s GDP?","options":["Agriculture","Manufacturing","Services","Mining"],"answer":2,"explanation":"The services (tertiary) sector contributes well over half of India’s gross value added, while agriculture employs the most people but contributes under a fifth of GDP.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-33","question":"The Consumer Price Index (Combined) used by the RBI for inflation targeting is released by the:","options":["Reserve Bank of India","National Statistical Office","Office of the Economic Adviser, DPIIT","NITI Aayog"],"answer":1,"explanation":"CPI (Combined) is published monthly by the NSO under the Ministry of Statistics; the WPI is released by the Office of the Economic Adviser, DPIIT.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-34","question":"Under the flexible inflation targeting framework, the RBI’s inflation target is:","options":["2% with a band of ±1%","4% with a band of ±2%","6% with a band of ±2%","5% with no band"],"answer":1,"explanation":"The RBI Act (amended 2016) sets a CPI inflation target of 4% with a tolerance band of 2% to 6%, reviewed every five years by the Government.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-35","question":"The Monetary Policy Committee of the RBI consists of how many members?","options":["4","5","6","8"],"answer":2,"explanation":"The MPC has six members: the Governor (chair), the Deputy Governor in charge of monetary policy, one RBI officer and three members nominated by the Central Government.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-36","question":"Under Article 280 of the Constitution, a Finance Commission is constituted by the President every:","options":["3 years","5 years","7 years","10 years"],"answer":1,"explanation":"A Finance Commission is set up every fifth year (or earlier) to recommend how tax proceeds are shared between the Union and the States.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-37","question":"Disguised unemployment in India is most commonly found in:","options":["The IT sector","Agriculture","Banking","Manufacturing"],"answer":1,"explanation":"In disguised unemployment more people are engaged than needed, so removing some would not reduce output; this is typical of family farms in rural India.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-38","question":"If nominal GDP grew by 10% in a year and the GDP deflator rose by 4%, real GDP grew by approximately:","options":["4%","6%","10%","14%"],"answer":1,"explanation":"Real growth ≈ nominal growth − inflation (deflator) = 10% − 4% ≈ 6%. Exactly, 1.10/1.04 − 1 ≈ 5.8%.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-39","question":"Which of the following is a capital receipt of the Government of India?","options":["Corporation tax","Dividends from public-sector enterprises","Recovery of loans given to States","Interest received on loans"],"answer":2,"explanation":"Capital receipts either create a liability (borrowings) or reduce an asset (loan recoveries, disinvestment). Taxes, dividends and interest are revenue receipts.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-40","question":"“Core inflation” is headline inflation with which items excluded?","options":["Housing and clothing","Food and fuel","Services and imports","Education and health"],"answer":1,"explanation":"Core inflation strips out the volatile food and fuel components to show the underlying trend in prices.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-41","question":"The Marginal Standing Facility (MSF) rate is normally kept at:","options":["25 basis points below the repo rate","Equal to the repo rate","25 basis points above the repo rate","100 basis points above the repo rate"],"answer":2,"explanation":"The MSF rate, at which banks borrow overnight from the RBI in an emergency against SLR securities, forms the ceiling of the LAF corridor, 25 bps above the repo rate; the SDF rate is 25 bps below.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-42","question":"Which RBI facility absorbs surplus liquidity from banks without the RBI giving any collateral?","options":["Repo","Reverse repo","Standing Deposit Facility","Marginal Standing Facility"],"answer":2,"explanation":"The SDF, introduced in April 2022, lets banks park funds with the RBI without the RBI providing securities, unlike the reverse repo; it is the floor of the LAF corridor.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-43","question":"The Phillips curve shows the relationship between:","options":["Inflation and unemployment","Savings and investment","Interest rate and money demand","Tax rate and tax revenue"],"answer":0,"explanation":"The Phillips curve shows an inverse relationship between inflation and unemployment; the tax rate–revenue relation is the Laffer curve.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-44","question":"The Lorenz curve is used to measure:","options":["Economic growth","Income inequality","Price elasticity","Balance of payments"],"answer":1,"explanation":"The Lorenz curve plots cumulative income against cumulative population; the farther it lies from the 45° line, the greater the inequality (summarised by the Gini coefficient).","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-45","question":"Which of the following is recorded in the current account of India’s balance of payments?","options":["Foreign direct investment","Remittances from Indians abroad","External commercial borrowings","Portfolio investment by FIIs"],"answer":1,"explanation":"The current account covers trade in goods and services, income and transfers such as remittances; FDI, FPI and borrowings are capital (financial) account items.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-46","question":"By the expenditure method, with private consumption ₹60 lakh crore, investment ₹20 lakh crore, government spending ₹15 lakh crore, exports ₹10 lakh crore and imports ₹15 lakh crore, GDP is:","options":["₹120 lakh crore","₹90 lakh crore","₹100 lakh crore","₹110 lakh crore"],"answer":1,"explanation":"GDP = C + I + G + (X − M) = 60 + 20 + 15 + (10 − 15) = 90 lakh crore; adding imports instead of subtracting gives the wrong 120.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-47","question":"How many of these statements are correct? I. The repo rate is the rate at which the RBI lends to banks against government securities. II. The reverse repo rate is higher than the repo rate. III. The bank rate is currently aligned with the MSF rate. IV. CRR is maintained by banks in the form of government securities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the reverse repo rate is below the repo rate. IV is wrong: CRR is cash kept with the RBI; it is the SLR that is held in government securities.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-48","question":"Assertion (A): A rise in the Statutory Liquidity Ratio reduces the lending capacity of banks. Reason (R): SLR requires banks to hold a prescribed share of their net demand and time liabilities in liquid assets such as government securities.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Money locked in SLR assets cannot be lent, so raising the SLR directly shrinks the funds available for credit; R states exactly that mechanism.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-49","question":"Match the budget concept with its definition: 1. Revenue deficit 2. Fiscal deficit 3. Primary deficit 4. Effective revenue deficit; a. Fiscal deficit minus interest payments b. Revenue deficit minus grants for creation of capital assets c. Revenue expenditure minus revenue receipts d. Total expenditure minus total non-borrowing receipts","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Revenue deficit = revenue expenditure − revenue receipts; fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts); primary deficit = fiscal deficit − interest; effective revenue deficit = revenue deficit − grants-in-aid for capital assets.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-50","question":"A government has revenue receipts of ₹20 lakh crore, non-debt capital receipts of ₹2 lakh crore, total expenditure of ₹30 lakh crore and interest payments of ₹8 lakh crore. Its primary deficit is:","options":["₹8 lakh crore","₹10 lakh crore","₹2 lakh crore","Zero"],"answer":3,"explanation":"Fiscal deficit = 30 − (20 + 2) = ₹8 lakh crore; primary deficit = fiscal deficit − interest = 8 − 8 = 0. Forgetting the non-debt capital receipts gives the wrong ₹2 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-51","question":"How many of these statements about GST are correct? I. The GST Council is a constitutional body under Article 279A. II. In the Council, the Centre’s vote has a weight of one-third and the States together two-thirds. III. GST compensation to States was guaranteed for five years from 1 July 2017. IV. Petrol and diesel are taxed under GST at 28%.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (decisions need a three-fourths weighted majority). IV is wrong: petrol, diesel, ATF, natural gas and crude are outside GST until the Council decides otherwise.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-52","question":"Which of the following is NOT included in the M1 measure of money supply?","options":["Currency with the public","Demand deposits with banks","Time deposits with banks","Other deposits with the RBI"],"answer":2,"explanation":"M1 (narrow money) = currency with the public + demand deposits + other deposits with the RBI. Time deposits enter only M3 (broad money).","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL"},
  {"id":"eco-basics-53","question":"Arrange these events in chronological order: 1. Formation of the State Bank of India 2. Nationalisation of the RBI 3. Launch of the First Five-Year Plan 4. Setting up of the Planning Commission","options":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","4, 3, 2, 1"],"answer":0,"explanation":"RBI nationalised on 1 January 1949; Planning Commission set up in March 1950; First Plan began in April 1951; SBI formed on 1 July 1955.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-54","question":"How many of these statements are correct? I. Frictional unemployment occurs when workers are temporarily between jobs. II. Structural unemployment arises from a mismatch between workers’ skills and available jobs. III. Cyclical unemployment rises during a recession. IV. In disguised unemployment the marginal productivity of the extra workers is zero.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are standard definitions: frictional (search time), structural (skill mismatch), cyclical (demand downturn) and disguised (surplus labour with zero marginal product).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-55","question":"Assertion (A): During a period of high inflation, borrowers gain at the expense of lenders. Reason (R): Inflation reduces the real value of the money that is repaid.","options":["A is true but R is false","Both A and R are true but R does not explain A","Both A and R are true and R explains A","A is false but R is true"],"answer":2,"explanation":"A fixed sum repaid later buys less after inflation, so the lender receives less real value and the borrower effectively repays less; R is precisely the reason.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-56","question":"A country’s GDP at market prices is ₹500 lakh crore, net factor income from abroad is −₹20 lakh crore, depreciation is ₹50 lakh crore and net indirect taxes are ₹30 lakh crore. Its national income (NNP at factor cost) is:","options":["₹400 lakh crore","₹440 lakh crore","₹460 lakh crore","₹480 lakh crore"],"answer":0,"explanation":"GNP = 500 − 20 = 480; NNP at market prices = 480 − 50 = 430; NNP at factor cost = 430 − 30 = 400 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-57","question":"How many of these statements are correct? I. The Fifteenth Finance Commission recommended devolving 41% of the divisible pool of central taxes to the States. II. Corporation tax is a direct tax. III. Customs duty collected by the Union forms part of the divisible pool shared with States. IV. Cesses levied by the Union are part of the divisible pool.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: cesses and surcharges are retained wholly by the Centre and are excluded from the pool shared under Article 270.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"eco-basics-58","question":"Match the publication with the body that releases it: 1. Human Development Report 2. World Economic Outlook 3. Global Competitiveness Report 4. Ease of Doing Business (till 2021); a. World Bank b. IMF c. UNDP d. World Economic Forum","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-a, 3-d, 4-b","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a"],"answer":0,"explanation":"HDR and the HDI come from UNDP, the World Economic Outlook from the IMF, the Global Competitiveness Report from the WEF, and the (discontinued) Doing Business rankings were the World Bank’s.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "eco-basics-59", "question": "The economic reforms India began in 1991 are often summed up as “LPG”, which stands for:", "options": ["Liberalisation, Privatisation and Globalisation", "Licensing, Production and Growth", "Land, Population and GDP", "Liberalisation, Planning and Growth"], "answer": 0, "explanation": "The 1991 reforms (PM P. V. Narasimha Rao, Finance Minister Manmohan Singh) liberalised industry and trade, opened the public sector to private players and integrated India with the world economy.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-60", "question": "Which body regulates the securities (stock) market in India?", "options": ["RBI", "SEBI", "IRDAI", "PFRDA"], "answer": 1, "explanation": "SEBI, set up in 1988 and given statutory powers in 1992, regulates stock exchanges and securities. IRDAI regulates insurance and PFRDA pensions.", "difficulty": "easy", "source": "SSC GD · RRB Group D"},
  {"id": "eco-basics-61", "question": "India’s First Five-Year Plan (1951–56) gave the highest priority to:", "options": ["Heavy industry", "Defence", "Agriculture, including irrigation", "Exports"], "answer": 2, "explanation": "The First Plan, based on the Harrod–Domar model, focused on agriculture and irrigation after Partition-era food shortages. Heavy industry was the focus of the Second Plan.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-62", "question": "The Second Five-Year Plan, which stressed rapid industrialisation through heavy industries, was based on the model of:", "options": ["Harrod and Domar", "P. C. Mahalanobis", "D. R. Gadgil", "Arthur Lewis"], "answer": 1, "explanation": "The Second Plan (1956–61) followed the Mahalanobis model of building capital-goods industries. The Harrod–Domar model underlay the First Plan.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-63", "question": "A Gini coefficient of 0 indicates:", "options": ["Perfect inequality", "Zero inflation", "Zero GDP growth", "Perfect equality of income"], "answer": 3, "explanation": "The Gini coefficient runs from 0 (everyone has the same income) to 1 (one person has all the income); it is derived from the Lorenz curve.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-64", "question": "Which organisation replaced the General Agreement on Tariffs and Trade (GATT) in 1995?", "options": ["IMF", "World Bank", "World Trade Organization", "UNCTAD"], "answer": 2, "explanation": "The WTO came into being on 1 January 1995 after the Uruguay Round, replacing GATT (1947). The IMF and World Bank date from the 1944 Bretton Woods conference.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-65", "question": "Inflation caused by a rise in the prices of raw materials, wages or fuel is called:", "options": ["Demand-pull inflation", "Cost-push inflation", "Stagflation", "Deflation"], "answer": 1, "explanation": "When production costs rise, firms raise prices: cost-push inflation. Demand-pull inflation comes from too much demand chasing limited goods.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-66", "question": "Gresham’s law in economics states that:", "options": ["Good money drives bad money out of circulation", "Bad money drives good money out of circulation", "Supply creates its own demand", "The quantity of money determines the price level"], "answer": 1, "explanation": "When two forms of money of the same face value circulate, people hoard the more valuable (good) one and spend the debased (bad) one. “Supply creates its own demand” is Say’s law.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-67", "question": "Goods whose demand rises when their price rises, typically cheap staple foods consumed by very poor households, are called:", "options": ["Veblen goods", "Giffen goods", "Normal goods", "Complementary goods"], "answer": 1, "explanation": "Giffen goods are inferior staples: a price rise makes the poor too poor to afford better food, so they buy more of the staple. Veblen goods also defy the law of demand, but they are luxury status goods.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-68", "question": "A devaluation of the rupee generally makes:", "options": ["Indian exports cheaper for foreign buyers and imports costlier in India", "Both exports and imports cheaper", "Indian exports costlier and imports cheaper", "No difference to exports and imports"], "answer": 0, "explanation": "After devaluation a dollar buys more rupees, so Indian goods become cheaper abroad while foreign goods cost more rupees at home.", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-69", "question": "The official poverty estimate of 21.9% for India in 2011–12 was based on the methodology of which committee?", "options": ["Lakdawala Committee", "Rangarajan Committee", "Alagh Committee", "Tendulkar Committee"], "answer": 3, "explanation": "The Planning Commission’s 2011–12 estimate of 21.9% used the Tendulkar methodology. The Rangarajan Committee (2014) proposed a higher line giving 29.5%, but it was not formally adopted.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-70", "question": "The term “twin deficit” refers to an economy running:", "options": ["A revenue deficit and a primary deficit together", "A fiscal deficit and a current account deficit together", "A trade deficit and a services deficit together", "A budget deficit in two consecutive years"], "answer": 1, "explanation": "Twin deficits mean the government spends more than it earns (fiscal deficit) while the country spends more abroad than it earns (current account deficit).", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-71", "question": "In Indian planning, the period of “Plan Holiday”, when annual plans replaced a five-year plan, was:", "options": ["1962–65", "1985–87", "1966–69", "1978–80"], "answer": 2, "explanation": "After the Third Plan (1961–66), war and drought led to three annual plans in 1966–69. 1978–80 was the Janata government’s “rolling plan”, a different arrangement.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-72", "question": "In India, an investment of 10% or more of the post-issue equity of a listed company by a foreign investor is classified as:", "options": ["Foreign portfolio investment", "Foreign direct investment", "External commercial borrowing", "A non-resident deposit"], "answer": 1, "explanation": "Following the Mayaram Committee, the 10% line separates FDI (a lasting interest) from FPI (below 10% in a listed company).", "difficulty": "hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-73", "question": "How many of these are direct taxes in India? I. Corporation tax II. Customs duty III. Securities transaction tax IV. Capital gains tax", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Corporation tax, securities transaction tax and capital gains tax are direct taxes administered by the CBDT. Customs duty is an indirect tax under the CBIC. STT is the usual trap.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-74", "question": "Assertion (A): Indirect taxes are generally regressive. Reason (R): An indirect tax on a good is the same for every buyer, so it takes a larger share of a poor person’s income than of a rich person’s.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Everyone pays the same tax on, say, a packet of salt, which is a bigger fraction of a low income. R correctly explains why A is true.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-75", "question": "Match the term with its meaning: 1. Demand-pull inflation 2. Cost-push inflation 3. Stagflation 4. Disinflation; a. A fall in the rate of inflation b. Excess aggregate demand pushing up prices c. Rising input costs pushing up prices d. High inflation along with stagnant output", "options": ["1-b, 2-c, 3-d, 4-a", "1-c, 2-b, 3-d, 4-a", "1-b, 2-c, 3-a, 4-d", "1-b, 2-d, 3-c, 4-a"], "answer": 0, "explanation": "Disinflation means prices still rise but more slowly; it differs from deflation, where the price level itself falls.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-76", "question": "Nominal GDP rises from ₹200 lakh crore to ₹264 lakh crore in a year while the GDP deflator rises from 100 to 120. The growth of real GDP is:", "options": ["32%", "12%", "10%", "20%"], "answer": 2, "explanation": "Real GDP in the second year = 264 ÷ 1.20 = ₹220 lakh crore. Growth = (220 − 200) ÷ 200 = 10%. 32% is the nominal growth and 12% is the trap of simple subtraction (32 − 20).", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "eco-basics-77", "question": "How many of these statements about MGNREGA are correct? I. It was enacted in 2005. II. It guarantees 100 days of wage employment in a financial year to every rural household whose adults volunteer for unskilled manual work. III. At least one-third of the beneficiaries are to be women. IV. Unemployment allowance is paid by the Central Government.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the unemployment allowance is the liability of the State Government, while the Centre bears the full cost of unskilled wages.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-78", "question": "Which of the following is NOT recorded in the current account of India’s balance of payments?", "options": ["Export of software services", "Remittances from Indians working abroad", "Foreign direct investment inflows", "Interest paid on external loans"], "answer": 2, "explanation": "The current account covers goods, services, primary income (such as interest) and transfers (such as remittances). FDI is an investment flow recorded in the capital/financial account.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-79", "question": "Arrange in chronological order: 1. Establishment of the WTO 2. Bretton Woods conference 3. Launch of GST in India 4. India’s new economic policy (LPG reforms)", "options": ["2, 4, 1, 3", "4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "Bretton Woods 1944 → LPG reforms 1991 → WTO 1995 → GST 2017.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-80", "question": "Assertion (A): A cut in the cash reserve ratio increases the lending capacity of banks. Reason (R): The RBI pays banks a high rate of interest on their CRR balances.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: a lower CRR frees deposits for lending. R is false: the RBI pays no interest on CRR balances, which is why banks prefer a lower CRR.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · UPSC Prelims"},
  {"id": "eco-basics-81", "question": "How many of these statements are correct? I. Firms under perfect competition are price takers. II. A monopolist is always a price taker. III. Under oligopoly, each firm takes its decisions independently of its rivals. IV. Products under monopolistic competition are differentiated.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and IV are correct. A monopolist is a price maker, and oligopolists are interdependent: each watches and reacts to its few rivals.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "eco-basics-82", "question": "If the marginal propensity to consume is 0.8, an increase in investment of ₹100 crore will raise national income by:", "options": ["₹80 crore", "₹125 crore", "₹500 crore", "₹400 crore"], "answer": 2, "explanation": "Investment multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5. Increase in income = 5 × 100 = ₹500 crore.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-83", "question": "How many of the following are used in calculating UNDP’s Human Development Index? I. Life expectancy at birth II. Mean years of schooling III. Expected years of schooling IV. Gross national income per capita (PPP) V. Poverty headcount ratio", "options": ["Only two", "Only three", "Only four", "All five"], "answer": 2, "explanation": "HDI combines health (life expectancy), education (mean and expected years of schooling) and standard of living (GNI per capita at PPP). Poverty is measured separately by the Multidimensional Poverty Index.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-84", "question": "Agriculture, fishing, forestry and mining belong to which sector of the economy?", "options": ["Secondary sector", "Tertiary sector", "Quaternary sector", "Primary sector"], "answer": 3, "explanation": "The primary sector draws goods directly from nature. Manufacturing and construction form the secondary sector, and services such as banking and transport the tertiary sector.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-85", "question": "According to the law of demand, other things remaining the same, when the price of a good falls its quantity demanded:", "options": ["Falls", "Stays the same", "First falls and then rises", "Rises"], "answer": 3, "explanation": "Price and quantity demanded move in opposite directions, so the demand curve slopes downward. Giffen goods are the rare exception.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-86", "question": "The Economic Survey of India, presented just before the Union Budget, is prepared under the guidance of the:", "options": ["Comptroller and Auditor General", "Governor of the RBI", "Chairman of NITI Aayog", "Chief Economic Adviser"], "answer": 3, "explanation": "The Economic Division of the Department of Economic Affairs (Ministry of Finance) prepares the Survey under the Chief Economic Adviser, and the Finance Minister tables it in Parliament.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-87", "question": "Engel’s law states that as a household’s income rises:", "options": ["The share of income spent on food falls", "The demand for luxuries falls", "The share of income saved falls", "The amount spent on food falls"], "answer": 0, "explanation": "The amount spent on food may still rise, but it rises more slowly than income, so the share of income going to food falls. This is why a falling food share is used as a sign of rising living standards.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-88", "question": "A vertical demand curve shows that the price elasticity of demand is:", "options": ["Equal to one", "Zero", "Infinite", "Greater than one"], "answer": 1, "explanation": "A vertical curve means the same quantity is bought at every price, so demand is perfectly inelastic (elasticity zero). A horizontal demand curve is the one with infinite elasticity.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-89", "question": "The opportunity cost of a choice is:", "options": ["The value of the next best alternative given up", "The sum of all alternatives given up", "The cost of producing one more unit", "The money paid for the chosen item"], "answer": 0, "explanation": "Opportunity cost is the value of the best option forgone, not of all options. The cost of one more unit is marginal cost.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-90", "question": "A good whose demand falls when consumers’ income rises is called a:", "options": ["Normal good", "Complementary good", "Luxury good", "Inferior good"], "answer": 3, "explanation": "With higher income people switch from inferior goods (for example coarse grains) to better substitutes. For normal and luxury goods demand rises with income. A Giffen good is a special kind of inferior good.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-91", "question": "In India, fiscal policy (decisions on taxation and government spending) is decided by the:", "options": ["NITI Aayog", "Securities and Exchange Board of India", "Reserve Bank of India", "Government of India through the Ministry of Finance"], "answer": 3, "explanation": "Fiscal policy is set by the government and voted through the Budget. Monetary policy (interest rates and money supply) is the RBI’s job, and NITI Aayog is a policy think tank.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-92", "question": "The term ‘demographic dividend’ refers to:", "options": ["Profits from population-control programmes", "Extra tax revenue from a growing population", "Money sent home by emigrants", "The growth potential when the working-age share of the population is large"], "answer": 3, "explanation": "When the share of people aged about 15–64 is high and dependants are few, more workers and savings can speed growth, if there are jobs and skills for them. India is in this phase now.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-93", "question": "The price of a good rises from ₹10 to ₹12 and its quantity demanded falls from 100 units to 90 units. The price elasticity of demand (in absolute value) is:", "options": ["0.2", "0.5", "1.0", "2.0"], "answer": 1, "explanation": "Change in quantity = −10/100 = −10%; change in price = 2/10 = 20%. Elasticity = 10% ÷ 20% = 0.5, so demand is inelastic. Inverting the ratio gives the trap answer 2.0.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-94", "question": "Under the GST rate rationalisation that took effect on 22 September 2025, the main GST slabs became:", "options": ["5%, 12%, 18% and 28%", "5% and 18%, with a special 40% rate for sin and luxury goods", "12% and 28% only", "A single rate of 18%"], "answer": 1, "explanation": "The GST Council in September 2025 cut the four main slabs (5, 12, 18, 28%) to two, 5% and 18%, and set a special 40% rate for items such as tobacco products and luxury goods.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-95", "question": "‘Crowding out’ in economics means that:", "options": ["Heavy government borrowing raises interest rates and reduces private investment", "Large firms drive small firms out of business", "Imports push domestic producers out of the market", "Rural workers migrate to overcrowded cities"], "answer": 0, "explanation": "When the government borrows heavily from the market it competes with private borrowers for loanable funds, pushing up interest rates so that some private investment is dropped.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-96", "question": "A ‘liquidity trap’ is a situation in which:", "options": ["Inflation is so high that people refuse to hold money", "The government cannot sell its bonds", "Banks hold too little cash to meet withdrawals", "Interest rates are so low that further increases in money supply fail to lower them or raise spending"], "answer": 3, "explanation": "Keynes described how, near a zero interest rate, people prefer to hold any extra money, so monetary policy loses its power and fiscal policy is needed. A bank running short of cash is a liquidity crisis, a different idea.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-97", "question": "The ‘paradox of thrift’ suggests that if all households try to save more at the same time:", "options": ["Interest rates will rise", "Total savings will rise sharply", "Investment will rise automatically", "Aggregate demand and income may fall, so total savings may not rise"], "answer": 3, "explanation": "Higher saving means lower consumption, which cuts demand, output and income; with lower income, total saving may stay the same or even fall. What is prudent for one family can hurt the economy as a whole.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-98", "question": "A fixed deposit pays 7% interest a year while consumer price inflation is 9%. The approximate real rate of return is:", "options": ["16%", "7%", "2%", "−2%"], "answer": 3, "explanation": "Real return ≈ nominal rate − inflation = 7% − 9% = −2%. The depositor’s money buys less at the end of the year than at the start, even though it has earned interest.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-99", "question": "According to the Periodic Labour Force Survey (PLFS) 2023–24, which sector employs the largest share of India’s workforce?", "options": ["Construction", "Manufacturing", "Services", "Agriculture and allied activities"], "answer": 3, "explanation": "Agriculture employs about 46% of workers even though it contributes less than a fifth of GVA, while services contribute the largest share of output. This gap is the root of disguised unemployment in farming.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-100", "question": "In the Union Budget 2025–26, the Government of India set its fiscal deficit target at:", "options": ["4.4% of GDP", "6.4% of GDP", "3.0% of GDP", "5.9% of GDP"], "answer": 0, "explanation": "The Budget for 2025–26 aimed at a fiscal deficit of 4.4% of GDP, down from 4.8% (revised estimate) in 2024–25. 5.9% and 6.4% were the targets of 2023–24 and 2022–23.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-101", "question": "‘Hot money’ refers to:", "options": ["Cash kept by the RBI for emergencies", "Short-term capital that moves quickly between countries to chase higher returns", "Money earned from illegal activities", "Counterfeit currency"], "answer": 1, "explanation": "Hot money is mainly short-term portfolio flows that rush in when interest rates or returns are attractive and leave just as fast, which can destabilise exchange rates. Black money is the term for illegal income.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-102", "question": "How many of these statements about price elasticity of demand are correct? I. Demand for necessities tends to be inelastic. II. A good with many close substitutes has elastic demand. III. If demand is elastic, a cut in price raises total expenditure on the good. IV. Elasticity is the same at every point on a straight-line, downward-sloping demand curve.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: on a straight-line demand curve elasticity falls from very high near the price axis to zero at the quantity axis, being 1 at the midpoint, even though the slope is constant.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-103", "question": "Assertion (A): Under a progressive income tax, the average tax rate rises as income rises. Reason (R): Under a progressive tax, the marginal tax rate is lower than the average tax rate.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true but R is false. In a progressive system the marginal rate (on the last rupee) is higher than the average rate, and it is exactly this that pulls the average rate up as income grows.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-104", "question": "Match the economist with the idea: 1. Adam Smith 2. J. M. Keynes 3. Thomas Malthus 4. David Ricardo; a. Comparative advantage b. Population tends to outgrow the food supply c. Effective demand determines output and employment d. The ‘invisible hand’ of the market", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-a, 2-c, 3-b, 4-d", "1-d, 2-c, 3-a, 4-b"], "answer": 1, "explanation": "Smith (Wealth of Nations, 1776) wrote of the invisible hand, Keynes (General Theory, 1936) of effective demand, Malthus of population outrunning food, and Ricardo of comparative advantage in trade.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-105", "question": "In a two-sector economy, consumption is C = 100 + 0.75Y and investment is fixed at ₹150 crore (all figures in ₹ crore). The equilibrium level of national income is:", "options": ["₹1,000 crore", "₹250 crore", "₹400 crore", "₹600 crore"], "answer": 0, "explanation": "At equilibrium Y = C + I = 100 + 0.75Y + 150, so 0.25Y = 250 and Y = ₹1,000 crore. Equivalently, autonomous spending of 250 × multiplier 1/(1 − 0.75) = 4 gives 1,000.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-106", "question": "Arrange these in chronological order: 1. Nationalisation of 14 major commercial banks 2. Industrial Policy Resolution adopted 3. FEMA enacted to replace FERA 4. High-yielding varieties programme that began the Green Revolution", "options": ["4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 3, 1", "2, 4, 1, 3"], "answer": 3, "explanation": "The Industrial Policy Resolution came in 1956, the high-yielding varieties programme in 1966, bank nationalisation in July 1969, and the Foreign Exchange Management Act in 1999.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-107", "question": "How many of these statements about price indices in India are correct? I. The Wholesale Price Index does not cover services. II. The Consumer Price Index covers both goods and services. III. The GDP deflator covers all goods and services produced in the country. IV. The Wholesale Price Index is compiled and released by the RBI.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the WPI is released by the Office of the Economic Adviser in the Department for Promotion of Industry and Internal Trade, while CPI is released by the National Statistics Office.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-108", "question": "Which of the following would NOT be counted in India’s GDP for the year?", "options": ["Value of new houses built during the year", "Salary paid to a government-school teacher", "Value of wheat a farmer grows and keeps for his own family", "Price received for selling a five-year-old car"], "answer": 3, "explanation": "GDP counts only goods and services produced in the year, so the resale of a used car is excluded (only a dealer’s commission would count). Production for own use, like the farmer’s wheat, is imputed and included.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-109", "question": "Assertion (A): After a devaluation, a country’s trade balance often worsens at first before it improves. Reason (R): Import bills rise at once because of the higher prices, while export and import volumes take time to adjust.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "This is the J-curve effect: in the short run contracts are fixed and demand is inelastic, so the higher rupee cost of imports widens the deficit; later, cheaper exports and costlier imports change volumes and the balance improves. R explains A.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-110", "question": "Match the committee with its subject: 1. Rangarajan Committee (2014) 2. Raja Chelliah Committee (1991) 3. Malhotra Committee (1993) 4. Abid Hussain Committee (1997); a. Small-scale industries b. Insurance sector reforms c. Tax reforms d. Measurement of poverty", "options": ["1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a"], "answer": 0, "explanation": "Rangarajan reviewed poverty estimation, Raja Chelliah recommended tax reforms in 1991, R. N. Malhotra opened up insurance (leading to IRDA), and Abid Hussain studied small-scale industries.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-111", "question": "In a year, nominal GDP grows by 12%, the GDP deflator rises by 5% and population grows by 2%. The approximate growth in real per capita income is:", "options": ["3%", "7%", "5%", "10%"], "answer": 2, "explanation": "Real GDP growth ≈ 12% − 5% = 7%; real per capita growth ≈ 7% − 2% = 5%. Stopping at 7% forgets population, and 10% wrongly ignores inflation.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · RBI Grade B"},
  {"id": "eco-basics-112", "question": "How many of these statements about the Union Budget are correct? I. Article 112 of the Constitution requires an Annual Financial Statement to be laid before Parliament. II. A Money Bill can be introduced only in the Lok Sabha. III. The Consolidated Fund of India is provided for in Article 266. IV. The Contingency Fund of India is placed at the disposal of the Finance Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: under Article 267 the Contingency Fund is at the disposal of the President, who can advance money from it for unforeseen spending pending Parliament’s approval.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-113", "question": "Assertion (A): A large fiscal deficit financed by borrowing directly from the central bank tends to be inflationary. Reason (R): Such monetisation of the deficit increases the base money in the economy.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "When the central bank buys government debt with newly created money, reserve (base) money rises and, through the money multiplier, broad money rises too; more money chasing the same goods pushes up prices. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "eco-basics-114", "question": "The basic economic problem of choice arises because:", "options": ["Money is printed by the central bank", "Resources are limited while human wants are unlimited", "Prices keep rising", "Governments collect taxes"], "answer": 1, "explanation": "Scarcity of land, labour and capital relative to wants forces every society to decide what to produce, how and for whom.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-115", "question": "A market with only one seller of a product that has no close substitutes is called:", "options": ["Monopoly", "Oligopoly", "Perfect competition", "Monopsony"], "answer": 0, "explanation": "A monopolist controls the whole supply and can set the price. Monopsony is the opposite case: a single buyer.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "eco-basics-116", "question": "A market dominated by a few large sellers, each of whose pricing decisions affects the others, is called:", "options": ["Monopolistic competition", "Perfect competition", "Oligopoly", "Monopoly"], "answer": 2, "explanation": "In an oligopoly, such as telecom or aviation, a handful of firms watch and react to one another's moves. Monopolistic competition has many sellers of differentiated goods.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-117", "question": "If the price of petrol rises sharply, the demand for petrol cars is likely to:", "options": ["Rise, because cars and petrol are substitutes", "Stay unchanged", "Rise, because cars become cheaper", "Fall, because cars and petrol are complements"], "answer": 3, "explanation": "Complements are used together, so a costlier complement makes the other good less attractive. With substitutes such as tea and coffee, a price rise of one raises demand for the other.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-118", "question": "To avoid double counting while measuring GDP, statisticians count:", "options": ["Only the value of final goods and services, or the value added at each stage", "The value of all goods sold, including raw materials", "Only exports", "Only goods produced by the government"], "answer": 0, "explanation": "Counting both wheat and the bread made from it would count the wheat twice. Using final goods or summing value added at each stage gives the same, correct total.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-119", "question": "A thirsty person gets less and less extra satisfaction from each additional glass of water. This illustrates the:", "options": ["Law of demand", "Law of diminishing marginal utility", "Law of supply", "Law of increasing returns"], "answer": 1, "explanation": "Marginal utility, the satisfaction from one more unit, falls as consumption rises. This is one reason why demand curves slope downward.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-120", "question": "Old-age pensions and scholarships paid by the government are NOT included in national income because they:", "options": ["Are too small to matter", "Are paid in cash", "Are transfer payments made without any current production in return", "Are counted in exports"], "answer": 2, "explanation": "Transfer payments merely move income from taxpayers to recipients; no good or service is produced for them, so including them would overstate output.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-121", "question": "A farmer sells wheat worth ₹100 to a miller (with no inputs bought), the miller sells flour worth ₹150 to a baker, and the baker sells bread worth ₹220 to consumers. How much do these transactions add to GDP?", "options": ["₹470", "₹370", "₹120", "₹220"], "answer": 3, "explanation": "Value added is ₹100 + ₹50 + ₹70 = ₹220, which equals the value of the final good, bread. Adding all sales (₹470) double-counts the wheat and flour.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-122", "question": "If the government fixes a maximum price (price ceiling) below the market equilibrium price, the most likely result is:", "options": ["A shortage, often accompanied by rationing or black markets", "A surplus of the good", "No change in the market", "A rise in the quantity supplied"], "answer": 0, "explanation": "At the lower price buyers want more and sellers offer less, so demand exceeds supply. A price floor above equilibrium, by contrast, creates a surplus.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-123", "question": "Luxury goods whose demand rises as their price rises, because a high price signals status, are called:", "options": ["Giffen goods", "Veblen goods", "Inferior goods", "Normal necessities"], "answer": 1, "explanation": "Veblen goods, such as designer watches, are prized for conspicuous consumption. Giffen goods are cheap staples of the very poor whose demand rises with price for a different reason.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-124", "question": "The cross-price elasticity of demand between two goods is negative. The two goods are most likely:", "options": ["Substitutes", "Unrelated", "Complements", "Both inferior goods"], "answer": 2, "explanation": "Negative cross elasticity means a rise in the price of one lowers demand for the other, as with printers and ink cartridges. Substitutes have positive cross elasticity.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-125", "question": "A factory dumps waste into a river, hurting fishermen downstream who receive no compensation. Economists call this a:", "options": ["Positive externality", "Public good", "Merit good", "Negative externality"], "answer": 3, "explanation": "A negative externality is a cost imposed on third parties outside the market. A corrective (Pigouvian) tax or regulation makes the polluter bear that cost.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "eco-basics-126", "question": "Goods like primary education and vaccination, which society considers so valuable that they would be under-consumed if left to the market, are called:", "options": ["Merit goods", "Demerit goods", "Giffen goods", "Inferior goods"], "answer": 0, "explanation": "Merit goods create benefits beyond the individual buyer, so governments subsidise or provide them. Demerit goods, such as tobacco, are over-consumed and often taxed.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-127", "question": "How many of these statements about price controls are correct? I. A price ceiling below the equilibrium price creates a shortage. II. A minimum support price above the market price can lead to large government stocks. III. Rationing often accompanies a binding price ceiling. IV. A price floor fixed below the equilibrium price changes the market outcome.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. A floor below equilibrium is non-binding: the market price already exceeds it, so nothing changes, and IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-128", "question": "Match the market form with its feature. A. Perfect competition  B. Monopoly  C. Monopolistic competition  D. Oligopoly; 1. Many sellers of differentiated products such as toothpaste brands  2. A few interdependent sellers  3. A single seller with no close substitutes  4. Many sellers of an identical product, each a price taker", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-4, B-1, C-3, D-2"], "answer": 1, "explanation": "Perfect competitors cannot influence price; a monopolist faces no rival; monopolistic competitors compete through branding and product differences; oligopolists react to each other's moves.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-129", "question": "How many of these statements about public goods are correct? I. One person's use does not reduce what is available to others (non-rival). II. It is hard to stop non-payers from using them (non-excludable). III. The free-rider problem means markets tend to under-supply them. IV. A public good must be produced by a government-owned enterprise.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; national defence and street lighting are classic examples. Governments usually fund or arrange public goods, but private firms can produce them under contract, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-130", "question": "Assertion (A): A rising GDP does not necessarily mean rising economic welfare. Reason (R): GDP leaves out unpaid household work and does not subtract environmental damage, and it says nothing about how income is distributed.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "These gaps are exactly why GDP can grow while welfare stagnates, and why measures such as the HDI and green accounting were developed.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "eco-basics-131", "question": "How many of these are correctly treated in India's GDP? I. The sale of a used car is excluded, except for the dealer's commission. II. Buying shares on the stock exchange is excluded. III. An imputed rent for owner-occupied houses is included. IV. Interest the government pays on its past borrowing is included as factor income.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Interest on public debt, much of it raised for consumption or war, is treated as a transfer payment rather than income from current production, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "eco-basics-132", "question": "Match the cost concept with an example or definition. A. Fixed cost  B. Variable cost  C. Marginal cost  D. Average cost; 1. Extra cost of producing one more unit  2. Total cost divided by the number of units  3. Rent of a factory that stays the same whatever the output  4. Raw materials, which rise as output rises", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Fixed costs must be paid even at zero output; variable costs change with output; marginal cost is the addition from one more unit; average cost spreads the total over all units.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "eco-basics-133", "question": "For an economy where depreciation is positive, net indirect taxes are positive, and net factor income from abroad is positive but smaller than net indirect taxes, arrange these in decreasing order: 1. GNP at market prices  2. NNP at factor cost  3. GDP at market prices  4. NDP at market prices", "options": ["1-3-4-2", "3-1-4-2", "1-3-2-4", "1-4-3-2"], "answer": 0, "explanation": "GNP(MP) = GDP(MP) + NFIA, so 1 > 3; NDP(MP) = GDP(MP) − depreciation, so 3 > 4; NNP(FC) = NDP(MP) + NFIA − net indirect taxes, which is below NDP(MP) because NFIA is smaller than net indirect taxes.", "difficulty": "very-hard", "source": "UPSC Prelims · IBPS PO"},
];

export default questions;
